    const onPageShow = (event: PageTransitionEvent) => {
      const { state: current } = store.getState();
      if (event.persisted && current.name === 'Review')
        store.setState({ state: { name: 'Plans', ctx: current.ctx, view: {} }, effects: [] });
    };
