import { trackThenRedirect } from '@/analytics/analytics/analytics';
import { createOrder } from '@/api/client/client';
import { isApiError, networkError } from '@/api/errors/errors';
import { grossCents } from '@/domain/money/money';
import { hasTrial, planKeyFor } from '@/domain/plans/plans';
import { buildReturnUrl } from '@/flow/context/context';
import type { FlowContext, FlowEffect, FlowEvent } from '@/flow/machine/machine';
import type { OpenOrder } from '@/flow/openOrder/openOrder';
import type { UtmSet } from '@/flow/utm/utm';

export type OrderSnapshot = OpenOrder['snapshot'];

export type ReviewPlan = { id: string; priceNet: number; vatRate: number; currency: string };

// `purchase` snapshot (07): what the user saw on Review. Trial shown → value and tax are 0.
export function buildOrderSnapshot(plan: ReviewPlan, trialEligible: boolean): OrderSnapshot {
  const planKey = planKeyFor(plan.id);
  const trial = planKey ? hasTrial(planKey, trialEligible) : false;
  const gross = grossCents(plan.priceNet, plan.vatRate);
  return {
    value: trial ? 0 : gross / 100,
    tax: trial ? 0 : (gross - plan.priceNet) / 100,
    currency: plan.currency,
    trial: trial ? 'true' : 'false',
  };
}

export type OrderAttempt = { ctx: FlowContext; utm: UtmSet; snapshot: OrderSnapshot };

export type CreateOrderDeps = {
  // Read when the effect runs: the attempt is whatever Review showed at Pay.
  attempt: () => OrderAttempt;
  origin: string;
  saveOpenOrder: (order: OpenOrder) => void;
  navigate: (url: string) => void;
};

// Runs CreatingOrder's effects (04). Slice: no attempt marker (04 Slice, Q39).
export function createOrderRunner(deps: CreateOrderDeps) {
  let saved: OpenOrder | null = null;
  return (effect: FlowEffect, dispatch: (event: FlowEvent) => void): boolean => {
    switch (effect.type) {
      case 'createOrder': {
        const { ctx, utm } = deps.attempt();
        const planKey = planKeyFor(effect.planId) ?? null;
        const returnUrl = buildReturnUrl(deps.origin, '/payment/return', {
          plan: planKey,
          market: ctx.market,
          locale: ctx.locale,
          utm,
          orderId: null,
        });
        createOrder({ planId: effect.planId, market: ctx.market, returnUrl }).then(
          ({ orderId, paymentUrl }) => dispatch({ type: 'orderCreated', orderId, paymentUrl }),
          (error: unknown) =>
            dispatch({
              type: 'orderCreateFailed',
              error: isApiError(error) ? error : networkError(),
            }),
        );
        return true;
      }
      case 'saveOpenOrder': {
        const { ctx, snapshot } = deps.attempt();
        saved = {
          orderId: effect.orderId,
          paymentUrl: effect.paymentUrl,
          planId: ctx.planId ?? '',
          market: ctx.market,
          locale: ctx.locale,
          snapshot,
        };
        deps.saveOpenOrder(saved);
        return true;
      }
      case 'redirect': {
        const order = saved;
        trackThenRedirect(
          'payment_started',
          { plan_id: order?.planId ?? '', transaction_id: order?.orderId ?? '' },
          () => deps.navigate(effect.url),
        );
        return true;
      }
      default:
        return false;
    }
  };
}
    const abort = new AbortController();
    const { dispatch } = store.getState();

    const loadTrialEligibility = () =>
      fetchMe(apiBase, abort.signal).then(
        (me) => {
          if (abort.signal.aborted) return;
          trialRef.current = me.trialEligible;
          setTrialEligible(me.trialEligible);
        },
        () => {
          // No trial claim without proof; Pay's Gate handles 401 and failures.
          trialRef.current = false;
          if (!abort.signal.aborted) setTrialEligible(false);
        },
      );

    const gateDeps: GateDeps = {
      getMe: (signal) => fetchMe(apiBase, signal),
      getOrder: (orderId, signal) => fetchOrder(apiBase, orderId, signal),
      clearOpenOrder: () => openOrder.clear(),
    };
    const runOrder = createOrderRunner({
      attempt: () => {
        const current = planRef.current;
        if (!current) throw new Error('unreachable: Pay stays disabled until the plan is loaded');
        return {
          ctx: store.getState().state.ctx,
          utm,
          snapshot: buildOrderSnapshot(current, trialRef.current),
        };
      },
      origin: window.location.origin,
      saveOpenOrder: (order) => openOrder.save(order),
      navigate,
    });
    const run = (effect: FlowEffect) => {
      if (effect.type === 'fetchPlans') {
        setFetching(true);
        getPlans(pair.market, abort.signal).then(
          ({ plans }) => {
            if (abort.signal.aborted) return;
            setFetching(false);
            setRetryingPlans(false);
            const found = plans.find((p) => p.id === store.getState().state.ctx.planId) ?? null;
            planRef.current = found;
            setPlan(found);
            dispatch({ type: 'plansChecked', planFound: found !== null });
          },
          (error: unknown) => {
            if (abort.signal.aborted) return;
            setFetching(false);
            setRetryingPlans(false);
            dispatch({ type: 'plansFailed', error: isApiError(error) ? error : networkError() });
          },
        );
        return;
      }
      if (runGateEffect(effect, dispatch, abort.signal, gateDeps)) return;
      runOrder(effect, dispatch);
    };

    const unsubscribe = store.subscribe((next, previous) => {
      if (next.state !== previous.state) {
        if (checkingRef.current) {
          checkingRef.current = false;
          setChecking(false);
          const stillDisabled = next.state.name === 'Review' && next.state.view.payDisabled;
          if (!stillDisabled) payRef.current?.focus();
        }
        if (next.state.name === 'Review' && previous.state.name !== 'Review') setConsent(false);
        const target = EXIT_STATES.includes(next.state.name)
          ? exitUrl(next.state, utm, accountUrl, window.location.origin)
          : null;
        if (target) {
          navigate(target);
          return;
        }
      }
      if (next.effects !== previous.effects) next.effects.forEach(run);
    });

    // Inv. 6: a bfcache restore (Back from payment) shows a fresh Review, Pay enabled, box unchecked.
    const onPageShow = (event: PageTransitionEvent) => {
      if (!event.persisted) return;
      const { state: current } = store.getState();
      setConsent(false);
      if (current.name === 'Review') {
        dispatch({ type: 'begin' });
      } else if (!isEidState(current)) {
        const ctx = { ...current.ctx, openOrderId: openOrder.read()?.orderId ?? null };
          return go({ name: 'Confirmed', ctx, orderId });
        case 'failed':
          return continueToMe();
      }
    }
    if (event.type === 'orderFailed') {
      switch (event.error.kind) {
        case 'orderNotFound':
          return continueToMe();
        case 'unauthenticated':
          return go({ name: 'IdentityLost', ctx, orderId });
        default:
          return retryPoint(ctx, { errorKind: event.error.kind, payDisabled: true });
      }
    }
    return stay(state);
  }

  if (event.type === 'meLoaded') {
    if (event.me.activeSubscription) return account(ctx);
    // Second pass after a 409: no second POST (Q41).
    if (ctx.conflictRetried) return retryPoint(ctx, { errorKind: 'conflict' });
    return go({ name: 'CreatingOrder', ctx });
  }
  if (event.type === 'meFailed')
    return event.error.kind === 'unauthenticated'
      ? startingEid({ ...ctx, identified: false })
      : retryPoint(ctx, { errorKind: event.error.kind });
  return stay(state);
}

function onCreatingOrder(
  state: Extract<FlowState, { name: 'CreatingOrder' }>,
  event: FlowEvent,
): Transition {
  const { ctx } = state;
  if (event.type === 'orderCreated')
    return {
      state: { ...state, ctx: { ...ctx, openOrderId: event.orderId } },
      effects: [
        { type: 'saveOpenOrder', orderId: event.orderId, paymentUrl: event.paymentUrl },
        { type: 'redirect', url: event.paymentUrl },
      ],
    };
  if (event.type !== 'orderCreateFailed') return stay(state);
  switch (event.error.kind) {
    case 'unauthenticated':
      return startingEid({ ...ctx, identified: false });
    case 'alreadySubscribed':
      return account(ctx);
    case 'invalidPlan':
      return go(plans(ctx, { notice: 'plan_unavailable' }));
    case 'conflict':
      return gateAfterConflict(ctx);
    default:
      return retryPoint(ctx, { errorKind: event.error.kind });
  }
}

// Shown again: stale disabled flags and consent error are dropped (inv. 6). The cross-page notice stays.
function onBegin(state: FlowState): Transition {
  switch (state.name) {
    case 'Gate':
    case 'CreatingOrder':
      return stay(state);
    case 'Review':
      return enter({
        ...state,
        view: { notice: state.view.notice },
        plansError: false,
        consentError: false,
      });
    case 'Plans':
      return stay({ ...state, view: { notice: state.view.notice } });
    default:
      return enter(state);
  }
}

// Display check of the open order behind a disabled Pay (04 Gate step 1, Q59). Never creates an order.
