// States that leave this page. Review itself is never an exit target.
const EXIT_STATES: readonly FlowState['name'][] = [
  'Plans',
  'Account',
  'PaymentReturn',
  'Confirmed',
  'IdentityLost',
];

export function Review(props: ReviewProps) {
  const [boot, setBoot] = useState<Boot | null>(null);

