import {
  chooseAndVerify,
  expect,
  heading,
  payAndCheckPolling,
  payFromReview,
  pollUntilVisible,
  test,
} from './support/fixtures';

const reviewOn = process.env.NEXT_PUBLIC_FLAG_REVIEW_STEP !== 'false';

test('lv/lv renders: lang, headline, 2 cards, 21% VAT', async ({ page, flow }) => {
  await page.goto('/lv/lv/');
  await expect(page.locator('html')).toHaveAttribute('lang', 'lv');
  await expect(heading(page)).toHaveText('Pasirinkite jums tinkamą planą');
  await expect(page.getByText(/10,88\s€/)).toBeVisible();
  await expect(page.getByText('Premium')).toHaveCount(0);
  await flow.checkScreen();
});

test('root picks lv/lv for a Latvian browser', async ({ browser }) => {
  const context = await browser.newContext({ locale: 'lv-LV' });
  const page = await context.newPage();
  await page.goto('/');
  await page.waitForURL('**/lv/lv/');
  await context.close();
});

test('lv/en full path → confirmed, order body market LV', async ({ page, flow }) => {
  const bodies: Record<string, unknown>[] = [];
  page.on('request', (r) => {
    if (r.method() === 'POST' && r.url().endsWith('/v1/orders')) bodies.push(r.postDataJSON());
  });
  await page.goto('/lv/en/');
  await flow.checkScreen();
  if (reviewOn) {
    await chooseAndVerify(page, flow, 'Standard', '/lv/en/review/');
    await expect(page.getByText(/€10\.88/)).toBeVisible();
    await flow.checkScreen();
    await payFromReview(page);
  } else {
    await chooseAndVerify(page, flow, 'Standard', '/mock-pay/');
  }
  await payAndCheckPolling(page, flow);
  await pollUntilVisible(page, heading(page).filter({ hasText: 'Payment confirmed' }));
  await flow.checkScreen({ focusMoves: true });
  expect(bodies).toHaveLength(1);
  expect(bodies[0]).toMatchObject({ planId: 'plan_std_m', market: 'LV' });
  const returnUrl = new URL(String(bodies[0].returnUrl));
  expect(returnUrl.searchParams.get('market')).toBe('lv');
  expect(await flow.orderCount()).toBe(1);
});
EOF
cd $S/app && rm -rf .next out; for R in true false; do echo "== reviewStep=$R"; NEXT_PUBLIC_FLAG_MARKET_LV=true NEXT_PUBLIC_FLAG_REVIEW_STEP=$R E2E_APP_PORT=3100 E2E_MOCK_PORT=4110 npx playwright test lv-probe 2>&1 | grep -vE "^\[WebServer\]" | grep -E "✓|✘|passed|failed|Error|Expected|Received|›" | head -20; done

